using System;class Program{static void Main(){uint a=4294967295U;uint b=2147483648U;Console.WriteLine(unchecked(a+b));Console.WriteLine(unchecked(a-b));Console.WriteLine(unchecked(a*b));Console.WriteLine(a/b);Console.WriteLine(a%b);Console.WriteLine(a>>33);Console.WriteLine(a>b);Console.WriteLine(b<a);Console.WriteLine(a>=b);Console.WriteLine(b<=a);try{Console.WriteLine(checked(a+1U));}catch(Exception error){Console.WriteLine(error.GetType().Name);}}}